301	    /**
302	     * Populate the owner's household size: the number of owners sharing this owner's
303	     * {@code householdId} (including the owner itself). An owner with no household is a household
304	     * of one.
305	     *
306	     * @param owner the owner whose household size should be computed and set
307	     */
308	    private void populateHouseholdSize(Owner owner) {
309	        String householdId = owner.getHouseholdId();
310	        if (!StringUtils.hasText(householdId)) {
311	            owner.setHouseholdSize(1);
312	            return;
313	        }
314	        int size = (int) this.clinicService.findAllOwners().stream()
315	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
316	            .count();
317	        owner.setHouseholdSize(size);
318	    }
319	
320	    /**
321	     * Generate a customer code formatted {@code <REGION>-<HASH8>}, where {@code REGION} is the region
322	     * code derived from the owner's identity (postcode range first, then the city-to-region table,
323	     * otherwise {@code UNKNOWN}) and {@code HASH8} is the first eight upper-case hex characters of the
324	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). There is no
325	     * longer any per-city sequence number.
326	     *
327	     * @param owner the owner whose (already-normalized) telephone, last name, postcode and city are read
328	     * @return the generated customer code
329	     */
330	    private String generateCustomerCode(Owner owner) {
331	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
332	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
333	        return region + "-" + hash8;
334	    }
335	
336	    /**
337	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
338	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
339	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
340	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
341	     * known region.
342	     *
343	     * @param postcode the owner's postcode, may be {@code null}
344	     * @param city     the owner's city
345	     * @return the derived region code
346	     */
347	    private String deriveRegion(String postcode, String city) {
348	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
349	            int value = Integer.parseInt(postcode);
350	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
351	                int[] range = entry.getValue();
352	                if (value >= range[0] && value <= range[1]) {
353	                    return entry.getKey();
354	                }
355	            }
356	        }
357	        String region = CITY_REGION.get(city);
358	        return region != null ? region : "UNKNOWN";
359	    }
360	
361	    /**
362	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
363	     * bytes of {@code input}.
364	     *
365	     * @param input  the value to digest
366	     * @param length the number of leading hex characters to return
367	     * @return the truncated upper-case hex digest
368	     */
369	    private String shortSha256Hex(String input, int length) {
370	        try {
371	            byte[] digest = MessageDigest.getInstance("SHA-256")
372	                .digest(input.getBytes(StandardCharsets.UTF_8));
373	            StringBuilder sb = new StringBuilder(digest.length * 2);
374	            for (byte b : digest) {
375	                sb.append(String.format("%02x", b));
376	            }
377	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
378	        } catch (java.security.NoSuchAlgorithmException e) {
379	            throw new IllegalStateException("SHA-256 not available", e);
380	        }
381	    }
382	
383	    /**
384	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
385	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
386	     * that is stored, returned and used for every value derived from it.
387	     *
388	     * @param date the effective registration date (supplied or defaulted)
389	     * @return the same date when it is a weekday, otherwise the next Monday
390	     */
391	    private LocalDate rollToBusinessDay(LocalDate date) {
392	        DayOfWeek dayOfWeek = date.getDayOfWeek();
393	        if (dayOfWeek == DayOfWeek.SATURDAY) {
394	            return date.plusDays(2);
395	        }
396	        if (dayOfWeek == DayOfWeek.SUNDAY) {
397	            return date.plusDays(1);
398	        }
399	        return date;
400	    }
401	
402	    /**
403	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
404	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
405	     *
406	     * @param customerCode     the owner's already-assigned customer code
407	     * @param registrationDate the owner's registration date
408	     * @return the generated membership number
409	     */
410	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
411	        String yy = String.format("%02d", registrationDate.getYear() % 100);
412	        return String.format("%s-M%s", customerCode, yy);
413	    }
