415	    /**
416	     * Count the existing owners that share the given first name and last name, comparing each
417	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
418	     * yet persisted, so it is not included in the count.
419	     *
420	     * @param firstName the incoming owner's first name
421	     * @param lastName  the incoming owner's last name
422	     * @return the number of existing namesakes
423	     */
424	    private int countNamesakes(String firstName, String lastName) {
425	        String normalizedFirstName = normalizeForComparison(firstName);
426	        String normalizedLastName = normalizeForComparison(lastName);
427	        return (int) this.clinicService.findAllOwners().stream()
428	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
429	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
430	            .count();
431	    }
