433	    /**
434	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
435	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
436	     *
437	     * @param city the incoming owner's city
438	     * @return the number of existing owners already in that city
439	     */
440	    private int countOwnersInCity(String city) {
441	        String normalizedCity = normalizeForComparison(city);
442	        return (int) this.clinicService.findAllOwners().stream()
443	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
444	            .count();
445	    }
