447	    /**
448	     * Count the existing owners whose registration date equals the given date. The incoming owner is
449	     * not yet persisted, so it is not included in the count.
450	     *
451	     * @param registrationDate the incoming owner's registration date
452	     * @return the number of existing owners already registered on that date
453	     */
454	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
455	        return (int) this.clinicService.findAllOwners().stream()
456	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
457	            .count();
