460	    /**
461	     * Find the existing owners that live in the same household as the given values, i.e. those that
462	     * share both the last name and the address when each is compared case-insensitively with
463	     * collapsed whitespace.
464	     *
465	     * @param lastName the incoming owner's last name
466	     * @param address  the incoming owner's address
467	     * @return the matching existing owners (possibly empty)
468	     */
469	    private List<Owner> findHouseholdMembers(String lastName, String address) {
470	        String normalizedLastName = normalizeForComparison(lastName);
471	        String normalizedAddress = normalizeForComparison(address);
472	        return this.clinicService.findAllOwners().stream()
473	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
474	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
475	            .toList();
