478	    /**
479	     * Generate a stable shared household identifier for the given last name and address. The value is
480	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
481	     * and address, so every owner joining the same household resolves to the same identifier. It is the
482	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
483	     *
484	     * @param lastName the household's last name
485	     * @param address  the household's address
486	     * @return the stable household identifier
487	     */
488	    private String generateHouseholdId(String lastName, String address) {
489	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
490	        return shortSha256Hex(key, 12);
491	    }
492	
493	    /**
494	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
495	     * single space, upper-case the result and expand common street-type abbreviations token by token
496	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
497	     * to the empty string. The result is the canonical form that is stored, returned and used for every
498	     * address comparison (household duplicate detection and the shared household id).
499	     *
500	     * @param address the raw address, may be {@code null}
501	     * @return the normalized address
502	     */
503	    private String normalizeAddress(String address) {
504	        if (address == null) {
505	            return "";
506	        }
507	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
508	        if (collapsed.isEmpty()) {
509	            return "";
510	        }
511	        String[] tokens = collapsed.split(" ");
512	        StringBuilder sb = new StringBuilder(collapsed.length());
513	        for (int i = 0; i < tokens.length; i++) {
514	            if (i > 0) {
515	                sb.append(' ');
516	            }
517	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
518	        }
519	        return sb.toString();
520	    }
521	
522	    /**
523	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
524	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
525	     *
526	     * @param value the raw value, may be {@code null}
527	     * @return the normalized value
528	     */
529	    private String normalizeForComparison(String value) {
530	        if (value == null) {
531	            return "";
532	        }
533	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
534	    }
535	
536	    /**
537	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
538	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
539	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
540	     * is returned lower-cased.
541	     *
542	     * @param email the raw email from the request payload, may be {@code null}
543	     * @return the lower-cased email, or {@code null} when none was provided
544	     */
545	    private String normalizeEmail(String email) {
546	        if (!StringUtils.hasText(email)) {
547	            return null;
548	        }
549	        if (!EMAIL_PATTERN.matcher(email).matches()) {
550	            throw new InvalidRequestException(List.of("email"));
551	        }
552	        return email.toLowerCase(Locale.ROOT);
553	    }
554	
555	    /**
556	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
557	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
558	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
559	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
560	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
561	     * to 400 Bad Request).
562	     *
563	     * @param city     the owner's city (used to resolve the region)
564	     * @param postcode the raw postcode from the request payload, may be {@code null}
565	     */
566	    private void validatePostcode(String city, String postcode) {
567	        if (!StringUtils.hasText(postcode)) {
568	            return;
569	        }
570	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
571	            throw new InvalidRequestException(List.of("postcode"));
572	        }
573	        String region = CITY_REGION.get(city);
574	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
575	        if (range != null) {
576	            int value = Integer.parseInt(postcode);
577	            if (value < range[0] || value > range[1]) {
578	                throw new InvalidRequestException(List.of("postcode"));
579	            }
580	        }
581	    }
582	
583	    /**
584	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
585	     * already carries a leading '+' keeps its country code; otherwise the default country code
586	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
587	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
588	     * is thrown (mapped to 400 Bad Request).
589	     *
590	     * @param telephone the raw telephone from the request payload
591	     * @return the E.164 string (e.g. {@code +61412345678})
592	     */
593	    private String normalizeTelephone(String telephone) {
594	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
595	        String candidate;
596	        if (cleaned.startsWith("+")) {
597	            candidate = cleaned;
598	        } else {
599	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
600	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
601	        }
602	        if (!E164_PATTERN.matcher(candidate).matches()) {
603	            throw new InvalidRequestException(List.of("telephone"));
604	        }
605	        // For country codes with a known fixed national-number length, reject a candidate whose
606	        // national digits (everything after the '+' and the country code) do not match that length.
607	        String digits = candidate.substring(1);
608	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
609	            String countryCode = entry.getKey();
610	            if (digits.startsWith(countryCode)) {
611	                int nationalLength = digits.length() - countryCode.length();
612	                if (nationalLength != entry.getValue()) {
613	                    throw new InvalidRequestException(List.of("telephone"));
614	                }
615	                break;
616	            }
617	        }
618	        return candidate;
619	    }
